steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issue(identifier: \"WEB-12\") { id identifier title description url } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issues(filter: { identifier: { eq: \"WEB-12\" } }) { nodes { id identifier title description url } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issues(filter: { search: { eq: \"WEB-12\" } }) { nodes { id identifier title } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{ __type(name: \"IssueFilter\") { inputFields { name type { name kind } } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issues(filter: { searchableContent: { eq: \"WEB-12\" } }) { nodes { id identifier title } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{ __type(name: \"ContentComparator\") { inputFields { name } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issues(filter: { searchableContent: { contains: \"WEB-12\" } }) { nodes { id identifier title } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issue(id: \"i-12\") { comments { id body user { id name } createdAt } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issue(id: \"i-12\") { comments { nodes { id body user { id name } createdAt } } } }"
  }'
